changeSet.sql:
create table if not exists public.benutzername_sperre (
    hash bytea primary key,
    erstellt timestamptz not null default clock_timestamp()
);
create table if not exists public.benutzername_sperre_status (
    id integer primary key check (id = 1),
    pruefwert bytea not null
);

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'archiv_app') then
        execute 'revoke all on public.benutzername_sperre from archiv_app';
        execute 'grant select, insert on public.benutzername_sperre to archiv_app';
        execute 'revoke all on public.benutzername_sperre_status from archiv_app';
        execute 'grant select on public.benutzername_sperre_status to archiv_app';
    end if;
end
$$
